mapper.sql:
FROM wf_instance i WHERE 1 = 1
AND i.applicant_id = #{userId}
AND i.status = 'RUNNING' AND EXISTS (
    SELECT 1 FROM wf_task t WHERE t.instance_id = i.id AND t.assignee_id = #{userId} AND t.status = 'PENDING')
AND i.status = #{status}
AND i.title LIKE CONCAT('%', #{kw}, '%')

mapper.update:
UPDATE wf_instance SET current_node=#{nodeKey}, current_node_name=#{nodeName}, status=#{status}
, finish_time = CURRENT_TIMESTAMP
WHERE id=#{id}

mapper.select:
SELECT t.*, i.title AS instance_title FROM wf_task t JOIN wf_instance i ON i.id = t.instance_id
WHERE t.assignee_id = #{assigneeId} AND t.status = 'PENDING' AND i.status = 'RUNNING'
ORDER BY t.id DESC LIMIT #{size} OFFSET #{offset}
